-- ====================================================================
-- SEED DỮ LIỆU CỤM RẠP CHO DỰ ÁN CINEMA BOOKING SYSTEM
-- Áp dụng cho bảng "cinema" trên DB PostgreSQL Render
-- Cột hợp lệ: cinemaid, name, address
-- ====================================================================

ON CONFLICT (cinemaid) DO UPDATE SET
    name = EXCLUDED.name,
    address = EXCLUDED.address;
